query siteValidWifiRadioSettings ( $accountId:ID! $validWifiRadioSettingsInput:ValidWifiRadioSettingsInput!) {
	site ( accountId:$accountId ) {
		validWifiRadioSettings ( input:$validWifiRadioSettingsInput  )  {
			band24 {
				standards
				channelWidths
				channels
			}
			band5 {
				standards
				channelWidths
				channels
			}
		}
	}	
}
